(function(){
  window.AP_LEARNING=window.AP_LEARNING||{};
  const M=(id,title,highYield,teaching,keyPoints,visualTitle,visualItems,mnemonic,goodToKnow,practiceConnection,prompt,options)=>({id,title,highYield,teaching,keyPoints,visual:{title:visualTitle,kind:'concept-map',items:visualItems.map(x=>({label:x[0],detail:x[1]}))},mnemonic:{title:mnemonic[0],cue:mnemonic[1],explanation:mnemonic[2]},goodToKnow,practiceConnection,activity:{prompt,options:options.map(x=>({text:x[0],correct:x[1],feedback:x[2]}))}});
  window.AP_LEARNING['lesson-8']={
    version:1,title:'The Articular System',chapter:8,duration:'60–80 minutes',
    outcomes:['Classify joints by structure and degree of movement.','Explain how a synovial joint balances mobility with stability.','Name common body movements from their direction and plane.','Match six synovial-joint shapes with examples and axes of motion.','Distinguish common joint injuries and disorders without diagnosing them.'],
    modules:[
      {id:'joint-language',title:'A map of every joint',summary:'Start with the two classification questions: what connects the bones, and how much can they move?',moments:[
        M('l8-m1','Structural and functional classifications','Structure and movement are two different naming systems.',[
          'A joint, or articulation, is where two or more skeletal elements meet. Structural classification asks what material joins the bones: fibrous tissue, cartilage, or a fluid-filled synovial cavity.',
          'Functional classification asks how much movement is possible. A synarthrosis is essentially immovable, an amphiarthrosis allows limited movement, and a diarthrosis moves freely. Most limb joints are diarthroses and structurally synovial.'
        ],['Fibrous, cartilaginous and synovial are structural groups.','Synarthroses do not move.','Amphiarthroses move slightly.','Diarthroses move freely.'],'Two lenses',[['Structure','What physically joins the bones?'],['Function','How much movement occurs?'],['Key pairing','Synovial joints are usually diarthroses']],['SAD movement scale','Synarthrosis · Amphiarthrosis · Diarthrosis','Think still, a little, dynamic.'],
        'The two systems overlap, but their terms are not interchangeable.',
        'Precise movement language helps a nutrition professional document mobility barriers without labeling their cause.',
        'Which functional class describes a freely movable shoulder joint?',[['Diarthrosis',true,'Correct. A freely movable joint is a diarthrosis.'],['Amphiarthrosis',false,'That class permits only slight movement.'],['Synarthrosis',false,'That class is essentially immovable.']]),
        M('l8-m2','Fibrous and cartilaginous joints','Less motion generally brings more stability.',[
          'Fibrous joints are united by dense connective tissue. Skull sutures are nearly immovable; a syndesmosis uses a ligament or membrane between bones; a gomphosis anchors a tooth in its socket.',
          'Cartilaginous joints join bones with cartilage. A synchondrosis uses hyaline cartilage, as in an epiphyseal plate before it closes. A symphysis uses fibrocartilage and allows limited movement, as at the pubic symphysis or between vertebral bodies.'
        ],['Suture and gomphosis are fibrous.','Syndesmosis uses fibrous tissue.','Synchondrosis uses hyaline cartilage.','Symphysis uses fibrocartilage.'],'Low-motion joints',[['Suture','Interlocking skull bones'],['Gomphosis','Tooth in socket'],['Synchondrosis','Hyaline cartilage bridge'],['Symphysis','Fibrocartilage pad']],['CH = cartilage','SynCHondrosis uses hyaline Cartilage','The shared sound helps separate it from a symphysis.'],
        'The former growth plate between a diaphysis and epiphysis is a classic synchondrosis.',
        'Joint structure can explain why a movement limitation is mechanically plausible, but it does not establish a diagnosis.',
        'Which joint is united by fibrocartilage and allows slight movement?',[['Symphysis',true,'Correct. Symphyses are cartilaginous amphiarthroses.'],['Suture',false,'A suture is fibrous and generally immovable.'],['Ball-and-socket',false,'That is a freely movable synovial form.']])
      ]},
      {id:'synovial-design',title:'The synovial-joint toolkit',summary:'A cavity, cartilage, capsule and lubricant create controlled, low-friction motion.',moments:[
        M('l8-m3','Inside a synovial joint','Articular cartilage reduces friction; fluid lubricates; ligaments guide and restrain.',[
          'At a synovial joint, the bone ends are capped by smooth articular cartilage and separated by a cavity. A capsule encloses the joint; its fibrous outer layer stabilizes while its inner synovial membrane produces synovial fluid.',
          'Ligaments connect bone to bone. Bursae are small fluid-filled sacs positioned where skin, tendon, ligament, or bone might rub. Menisci or discs in some joints improve fit and distribute load.'
        ],['Articular cartilage covers opposing bone ends.','Synovial fluid lubricates and nourishes cartilage.','Ligaments connect bone to bone.','Bursae reduce friction at pressure points.'],'Synovial layers',[['Cartilage','Smooth bearing surface'],['Cavity + fluid','Low-friction space'],['Capsule','Enclosure and stability'],['Ligament','Bone-to-bone restraint'],['Bursa','Friction-reducing sac']],['C-C-F-L-B','Cartilage · Capsule · Fluid · Ligament · Bursa','Rebuild the joint from the surfaces outward.'],
        'Subcutaneous bursae lie between skin and a bony prominence, such as around the knee or elbow.',
        'When a client reports pain or swelling, adapt movement-based goals and refer rather than trying to identify the injured structure.',
        'What directly provides lubrication inside a synovial cavity?',[['Synovial fluid',true,'Correct. It reduces friction between moving surfaces.'],['Sebum',false,'Sebum lubricates skin and hair, not joints.'],['A suture',false,'A suture is a fibrous joint.']]),
        M('l8-m4','Six joint shapes','Shape predicts available axes of motion.',[
          'Plane joints glide; hinge joints mainly flex and extend; pivot joints rotate around one axis. Condyloid joints move in two planes, saddle joints allow broad biaxial movement, and ball-and-socket joints move around multiple axes.',
          'Use anchor examples: intercarpal plane, elbow hinge, proximal radioulnar pivot, knuckle condyloid, thumb saddle, and shoulder or hip ball-and-socket. Ball-and-socket mobility is broad, but stability still depends on socket depth, capsule, ligaments and muscles.'
        ],['Hinge and pivot are uniaxial.','Condyloid and saddle are biaxial.','Ball-and-socket is multiaxial.','The thumb carpometacarpal joint is saddle shaped.'],'Shape-to-motion ladder',[['Plane','Glide'],['Hinge','Door-like arc'],['Pivot','Axial rotation'],['Condyloid','Two-plane oval'],['Saddle','Two-plane reciprocal curves'],['Ball-and-socket','Multiaxial sphere']],['Please Help People Cook Soup Bowls','Plane · Hinge · Pivot · Condyloid · Saddle · Ball-and-socket','Use the first letters to recall the six shapes.'],
        'The hip and shoulder share a joint type but differ in stability because their surrounding anatomy differs.',
        'Knowing axes of motion can help modify exercises around a known limitation while staying within an assigned care plan.',
        'Which joint type is found at the base of the thumb?',[['Saddle',true,'Correct. The thumb carpometacarpal joint is the classic saddle joint.'],['Hinge',false,'A hinge mainly flexes and extends.'],['Pivot',false,'A pivot rotates around one axis.']])
      ]},
      {id:'movement',title:'Decode movement words',summary:'Movement terms describe a direction, not a disease or level of ability.',moments:[
        M('l8-m5','Angle and midline movements','Flex/extend change an angle; abduct/adduct change distance from the midline.',[
          'Flexion decreases the angle between bones, while extension increases it. Hyperextension continues beyond the anatomical position. Abduction moves a part away from the midline; adduction returns it toward the midline.',
          'Circumduction combines flexion, extension, abduction and adduction so the distal end traces a circle. Rotation turns a bone around its long axis.'
        ],['Flexion decreases an angle.','Extension increases an angle.','Abduction moves away from the midline.','Adduction moves toward the midline.'],'Direction compass',[['Flexion','Close the angle'],['Extension','Open the angle'],['Abduction','Away from midline'],['Adduction','Add toward midline'],['Rotation','Turn around an axis']],['ABduct = away','ABduction begins with the same sound as away','Then adduction means add it back.'],
        'Pronation is not movement of the jaw; in the forearm it turns the palm posteriorly/downward from anatomical position.',
        'Use neutral descriptions such as “difficulty with ankle dorsiflexion” rather than assuming the cause.',
        'A leg moves laterally away from the body midline. What movement occurred?',[['Abduction',true,'Correct. Abduction moves away from the midline.'],['Adduction',false,'Adduction returns toward the midline.'],['Flexion',false,'Flexion changes the joint angle.']]),
        M('l8-m6','Special movements','Feet, forearms, jaw and shoulder girdles use specialized vocabulary.',[
          'Dorsiflexion brings the top of the foot toward the shin; plantar flexion points the foot. Inversion turns the sole inward and eversion turns it outward. Pronation and supination describe forearm rotation.',
          'Elevation raises a body part and depression lowers it. Protraction moves a structure anteriorly, while retraction moves it posteriorly. Opposition brings the thumb across the palm to meet a fingertip.'
        ],['Dorsiflexion lifts the foot.','Inversion and eversion apply to the foot.','Elevation and depression are opposites.','Opposition is central to thumb function.'],'Special-movement pairs',[['Dorsi / plantar','Foot up / point'],['Inversion / eversion','Sole in / out'],['Pronation / supination','Palm down / up'],['Elevation / depression','Raise / lower'],['Protraction / retraction','Forward / back']],['SOUPination','Supination holds a bowl of soup','Palm-up imagery separates it from pronation.'],
        'Movement descriptions assume the anatomical position unless the context says otherwise.',
        'Movement vocabulary can make accessibility planning specific: reach, grip, gait and meal preparation each demand different motions.',
        'Which movement raises the foot at the ankle?',[['Dorsiflexion',true,'Correct. Dorsiflexion brings the dorsum toward the shin.'],['Plantar flexion',false,'That points the foot downward.'],['Eversion',false,'That turns the sole outward.']])
      ]},
      {id:'applied-joints',title:'Stress, injury and joint conditions',summary:'Separate the injured structure from the movement affected and from the condition’s cause.',moments:[
        M('l8-m7','Sprain, strain and dislocation','The words identify different structures and events.',[
          'A sprain injures a ligament; a strain injures muscle or tendon. A dislocation occurs when articulating bone surfaces are displaced, while subluxation is partial displacement. These require appropriate clinical assessment rather than self-classification.',
          'Repetitive loading can irritate tendons or bursae and may contribute to compression syndromes such as carpal tunnel syndrome. A laminectomy is a surgical removal of part of a vertebral lamina to create space; it is not simply another word for dislocation.'
        ],['Sprain involves a ligament.','Strain involves muscle or tendon.','Dislocation changes joint congruence.','Bursitis is inflammation of a bursa.'],'Structure-first sorting',[['Ligament','Sprain'],['Muscle/tendon','Strain'],['Joint alignment','Dislocation'],['Bursa','Bursitis'],['Joint overall','Arthritis']],['SPRained Ligament','SPrain pairs with supporting ligament','Contrast it with STRain of muscle/tendon.'],
        'A temporarily displaced joint is still a safety concern even if it seems to move back into place.',
        'Nutrition support may help a person meet general recovery needs, but it does not replace assessment or rehabilitation.',
        'Which term best matches injury to a ligament?',[['Sprain',true,'Correct. Ligaments are the affected structure in a sprain.'],['Strain',false,'A strain affects muscle or tendon.'],['Arthritis',false,'Arthritis refers to joint inflammation/disease, not this injury category.']]),
        M('l8-m8','Arthritis patterns without shortcuts','Arthritis is a broad category; several mechanisms can affect a joint.',[
          'Osteoarthritis involves degeneration of joint structures over time and load. Rheumatoid arthritis is a systemic autoimmune connective-tissue disorder that often inflames small joints. Gout follows deposition of urate crystals, commonly affecting the joint at the base of the large toe.',
          'Shared symptoms such as pain, stiffness or swelling do not make the conditions equivalent. History, examination and testing guide diagnosis; anatomy study should help you understand the involved structures, not diagnose from a symptom list.'
        ],['Arthritis means joint inflammation/disease as a broad label.','Osteoarthritis is degenerative.','Rheumatoid arthritis is autoimmune/systemic.','Gout involves urate crystals.'],'Three mechanisms',[['Wear/degeneration','Osteoarthritis'],['Autoimmune inflammation','Rheumatoid arthritis'],['Crystal deposition','Gout']],['ORG','Osteoarthritis · Rheumatoid · Gout','Name the mechanism after the label.'],
        'Gout can involve other joints even though the first metatarsophalangeal joint is a classic site.',
        'Nutrition professionals can support evidence-based dietary goals within scope while coordinating with medical management.',
        'Which condition is associated with urate-crystal deposition?',[['Gout',true,'Correct. Urate crystals can inflame affected joints.'],['Rheumatoid arthritis',false,'That is an autoimmune disorder.'],['Bursitis',false,'That affects a bursa rather than describing crystal deposition.']])
      ]}
    ],
    caseStudy:{title:'Name the motion, then the structure',scenario:'A client with a clinician-confirmed wrist condition says repetitive chopping is difficult and asks what “kind of joint problem” it is.',prompts:['Describe the task using movement terms.','List the synovial structures that reduce friction or add stability.','Explain why symptoms alone cannot distinguish tendon, ligament, bursa or nerve involvement.','Suggest an appropriate scope-safe next step for meal-planning support.'],takeaway:'Use joint language to understand function and adapt the task; leave diagnosis and rehabilitation to the appropriate clinician.'},
    recap:['Joint structure and movement are separate classification systems.','Synarthroses are immovable, amphiarthroses slightly movable and diarthroses freely movable.','Synovial joints use cartilage, a capsule, fluid, ligaments and sometimes bursae or discs.','Joint shape predicts axes of movement.','Flex/extend change angles; abduct/adduct change position relative to the midline.','Sprain, strain and dislocation affect different structures or relationships.','Osteoarthritis, rheumatoid arthritis and gout have different mechanisms.'],
    flashcards:[{front:'Synarthrosis',back:'Functionally immovable joint.',tag:'classification'},{front:'Amphiarthrosis',back:'Slightly movable joint.',tag:'classification'},{front:'Diarthrosis',back:'Freely movable joint; most are synovial.',tag:'classification'},{front:'Synchondrosis',back:'Cartilaginous joint united by hyaline cartilage.',tag:'classification'},{front:'Symphysis',back:'Cartilaginous joint united by fibrocartilage.',tag:'classification'},{front:'Bursa',back:'Small fluid-filled sac that reduces friction.',tag:'structure'},{front:'Flexion',back:'Movement that decreases a joint angle.',tag:'movement'},{front:'Abduction',back:'Movement away from the midline.',tag:'movement'},{front:'Dorsiflexion',back:'Movement bringing the top of the foot toward the shin.',tag:'movement'},{front:'Saddle joint',back:'Biaxial synovial joint; classic example is the thumb base.',tag:'joint type'},{front:'Sprain',back:'Ligament injury.',tag:'injury'},{front:'Gout',back:'Inflammatory arthritis associated with urate crystals.',tag:'condition'}],
    practice:[{prompt:'Classify a skull suture structurally and functionally.',answer:'Fibrous joint and synarthrosis.',rationale:'Dense connective tissue unites bones with essentially no movement.',tag:'classification'},{prompt:'Why is a shoulder a diarthrosis?',answer:'It is a freely movable synovial joint.',rationale:'Diarthrosis is a functional movement class.',tag:'classification'},{prompt:'Distinguish synchondrosis from symphysis.',answer:'A synchondrosis uses hyaline cartilage; a symphysis uses fibrocartilage.',rationale:'The cartilage type is the key structural difference.',tag:'classification'},{prompt:'Name four core synovial-joint features.',answer:'Articular cartilage, joint cavity/fluid, capsule and reinforcing ligaments.',rationale:'Together they support low-friction controlled motion.',tag:'structure'},{prompt:'Match elbow, thumb base and hip to joint shape.',answer:'Hinge, saddle and ball-and-socket.',rationale:'These are anchor examples for the shape system.',tag:'joint type'},{prompt:'Contrast abduction and adduction.',answer:'Abduction moves away from the midline; adduction moves toward it.',rationale:'The midline is the reference.',tag:'movement'},{prompt:'What is the opposite of dorsiflexion?',answer:'Plantar flexion.',rationale:'It points the foot away from the shin.',tag:'movement'},{prompt:'Why does a sprain differ from a strain?',answer:'A sprain affects a ligament; a strain affects muscle or tendon.',rationale:'The injured structure defines the term.',tag:'injury'},{prompt:'Why is gout not interchangeable with rheumatoid arthritis?',answer:'Gout involves urate-crystal deposition; rheumatoid arthritis is autoimmune.',rationale:'Similar joint symptoms can arise from different mechanisms.',tag:'condition'},{prompt:'What does extension do to the angle between bones?',answer:'It increases the angle.',rationale:'Extension is the opposite of flexion.',tag:'movement'}]
  };
})();
